355:   private loadTerceroId(): void {
356:     const endpoint = `datos_identificacion?query=Activo:true,Numero:${this.documento}&sortby=FechaCreacion&order=desc`;
357:     this.loaderService.show();
358:     this.tercerosService.get(endpoint).pipe(takeUntilDestroyed(this.destroyRef), finalize(() => this.loaderService.hide())).subscribe((response: any) => {
359:       const data = response?.Data ?? response ?? [];
