1: import { BehaviorSubject, Subject } from 'rxjs';
2: import { Injectable } from '@angular/core';
3: import { RequestManager } from '../managers/requestManager';
4: import { decrypt } from 'src/utils/util-encrypt';
5:  
6:  
7: @Injectable({
8:   providedIn: 'root',
9: })
10: export class UserService {
11:   private user$ = new BehaviorSubject(null);
12:  
13:   constructor(private requestManager: RequestManager) {
14:     this.getUserInfo();
15:   }
16:  
17:   private getUserInfo() {
18:     const userLocalStorageEncode = window.localStorage.getItem('user');
19:     const userLocalStorage = userLocalStorageEncode
20:       ? JSON.parse(atob(userLocalStorageEncode))
21:       : null;
22:     this.user$.next(userLocalStorage);
23:   }
24:  
25:   public getId() {
26:     return localStorage.getItem(decrypt('persona_id'));
27:   }
28:  
29:   public getPersonaId(): number {
30:     const personaId = window.localStorage.getItem('persona_id');
31:     if (personaId === null) {
32:       return 0;
33:     }
34: 
35:     try {
36:       const decryptedPersonaId = decrypt(personaId);
37:       const thirdPartyId =
38:         typeof decryptedPersonaId === 'number'
39:           ? decryptedPersonaId
40:           : Number(decryptedPersonaId);
41: 
42:       return Number.isFinite(thirdPartyId) ? thirdPartyId : 0;
43:     } catch {
44:       return 0;
45:     }
46:   }
47:  
48:   public getUser() {
49:     if (!this.user$.value) {
50:       this.getUserInfo();
51:     }
52:     return this.user$.asObservable();
53:   }
54:  
55:   public getPayload(): any {
56:     var payload: any = {};
57:     const idToken = window.localStorage.getItem('id_token')?.split('.');
58:     if (idToken != undefined) {
59:       payload = JSON.parse(atob(idToken[1]));
60:     }
61:     return payload;
62:   }
63:  
64:   public esAutorizado(requiredRoles: string[]): Promise<boolean> {
65:     return new Promise((resolve, reject) => {
66:       this.getUser().subscribe(
67:         (user: any) => {
68:           if (user) {
69:             const tokenRoles = Array.isArray(user.user?.role)
70:               ? user.user.role
71:               : [];
72:             const serviceRoles = Array.isArray(user.userService?.role)
73:               ? user.userService.role
74:               : [];
75:             const roles = [...new Set([...tokenRoles, ...serviceRoles])];
76:             const isAuthorized = requiredRoles.some((role) =>
77:               roles.includes(role)
78:             );
79:             resolve(isAuthorized);
80:           } else {
81:             resolve(false);
82:           }
83:         },
84:         (error) => {
85:           reject(error);
86:         }
87:       );
88:     });
89:   }
90:  
91:   public getEmail(): Promise<string> {
92:     return new Promise((resolve, reject) => {
93:       this.getUser().subscribe(
94:         ({ user }: any) => {
95:           if (user && user.email) {
96:             resolve(user['email']);
97:           } else {
98:             resolve('');
99:           }
100:         },
101:         (error) => {
102:           console.error('Error al obtener el usuario', error);
103:           reject(error);
104:         }
105:       );
106:     });
107:   }
108:  
109:   public getPrograma(): number {
110:     return parseInt(window.localStorage.getItem('programa')!, 10);
111:   }
112:  
113:   public getPeriodo(): number {
114:     return parseInt(window.localStorage.getItem('IdPeriodo')!, 10);
115:   }
116: }

